<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Theme\Application\Usecase\Disable;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\Theme\Application\Service\Visibility\ThemeVisibilityService;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeDisableUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ThemeVisibilityService $visibility,
        private readonly ThemeWriteGateway $writer,
    ) {
    }

    public function allowDisable(?ThemeRef $ref = null): Allow
    {
        $this->logDebug("Check allow of Disable usecase for Theme");
        $span = $this->startSpan("Check allow of Disable usecase for Theme");
        try {
            $result = $this->dispatcher->dispatch(new ThemeDisableAllowDecision(Allow::allowed('disable', 'Allowed to Theme by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function disable(string $uid): ThemeDisableResult
    {
        $this->logDebug("Run Disable usecase for Theme");
        $span = $this->startSpan("Run Disable usecase for Theme");
        try {
            $ref = new ThemeRef($uid);
            $allow = $this->allowDisable($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to Disable Theme');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new ThemeDisableCheck($original));
            $modified = $original->disable();
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new ThemeDisableResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
